"""Freeze independent pre-corpus candidate scopes; no corpus read here."""
import hashlib,json
from pathlib import Path
H=Path(__file__).resolve().parent;(H/'NSC-002').mkdir(parents=True,exist_ok=True)
spec={'version':'1.0','stage':'PRE_CORPUS_FROZEN','candidates':[
 {'id':'A','title':'indicated-H monocyclic diazinone suffix','provisional_grammar':'[1H|3H]-pyrimidin-[2|4]-one with explicit H and carbonyl locants, single neutral component, no other substituents or suffixes','full_name':'Only fully consumed grammar; no external functional groups.','partial_operation':'Indicated-H and one suffix within a more complex parent remains potential, not supported until ownership and all affecting operations close.','authority':['https://iupac.qmul.ac.uk/BlueBook/P1.html#P-14.7','https://iupac.qmul.ac.uk/BlueBook/P6.html']},
 {'id':'B','title':'explicit neutral-to-cation pyridinium nomenclature','provisional_grammar':'pyridin-1-ium or N-locanted simple alkylpyridinium cation, single component, no counterion or additional substitution','full_name':'Exactly specified parent and cation; no inferred salts.','partial_operation':'A cation suffix inside a complex source is only potential until ownership and missing counterions are resolved.','authority':['https://iupac.qmul.ac.uk/BlueBook/P7.html','https://iupac.qmul.ac.uk/BlueBook/P1.html#P-13.3']},
 {'id':'C','title':'explicitly locanted halo/nitro substitution on benzene','provisional_grammar':'One to three prefix groups, each explicit locants 1..6, optional di or tri matching locant count, prefix bromo|chloro|fluoro|iodo|nitro, followed by benzene. Up to six distinct substitution positions, one connected neutral benzene parent, no suffix or other operations. Case-insensitive ASCII only, all other text must be consumed.','full_name':'Only complete supported name and validated multiplicity/ownership.','partial_operation':'Do not claim partial support when surrounding name is unparsed; embedded lexical matches are potential only.','authority':['https://iupac.qmul.ac.uk/BlueBook/P1.html#P-13.1','https://iupac.qmul.ac.uk/BlueBook/P1.html#P-14.2','https://iupac.qmul.ac.uk/BlueBook/P1.html#P-14.3','https://iupac.qmul.ac.uk/BlueBook/P5.html','https://old.goldbook.iupac.org/plain/N04158-plain.html']}
 ],'principles':['Freeze before corpus assessment; these are provisional scientific scopes, not parser results.','Partial substrings cannot prove source ownership or eligibility.','No chemistry is sourced from CUMA labels.']}
